        private static readonly Dictionary<string, string> NameById = Build();

        private static Dictionary<string, string> Build()
        {
            var d = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (var kv in IdByName) d[kv.Value] = kv.Key;
            return d;
        }

        /// The game's BlockTypes name for a player-facing item name.
        public static string IdFor(string displayName)
        {
            string id;
            return IdByName.TryGetValue(displayName ?? "", out id) ? id : null;
        }

        /// The player-facing name for a game block id.
        public static string NameFor(string blockId)
        {
            string name;
            return NameById.TryGetValue(blockId ?? "", out name) ? name : null;
        }

        public static int Count { get { return IdByName.Count; } }
    }
